import { useState, useEffect } from 'react';
const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');
export default function Leaderboard({ store }) {
  const [exams,   setExams]   = useState([]);
  const [selected,setSelected]= useState('');
  const [board,   setBoard]   = useState([]);
  const [loading, setLoading] = useState(false);
  const [myRank,  setMyRank]  = useState(null);
  const apiFetch = async p => { const r = await fetch(`${API}${p}`,{headers:{Authorization:`Bearer ${getToken()}`}}); return r.json(); };
  useEffect(()=>{ apiFetch('/exams').then(d=>{const a=Array.isArray(d)?d.filter(e=>e.status==='published'):[];setExams(a);if(a.length)setSelected(a[0].exam_id);}); },[]);
  useEffect(()=>{ if(!selected)return; setLoading(true); apiFetch(`/exams/${selected}/leaderboard`).then(d=>{const a=Array.isArray(d)?d:[];setBoard(a);setMyRank(a.find(r=>r.name===store.currentUser?.name)||null);setLoading(false);}); },[selected]);
  const gc = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':'#d97706';
  const medal = (i) => i===0?'🥇':i===1?'🥈':i===2?'🥉':null;
  return (
    <div className="fade-up">
      <h1 style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:26,color:'#0f0f1a',marginBottom:6}}>🏆 Leaderboard</h1>
      <p style={{fontSize:14,color:'#6b7280',marginBottom:20}}>Top performing students</p>
      <div style={{background:'#fff',border:'1px solid #e8e8f0',borderRadius:12,padding:'12px 16px',marginBottom:16,display:'flex',gap:8,flexWrap:'wrap',alignItems:'center',boxShadow:'0 1px 3px rgba(0,0,0,.05)'}}>
        <span style={{fontSize:12,color:'#6b7280',fontWeight:600,marginRight:4}}>Select Exam:</span>
        {exams.map(e=>(<button key={e.exam_id} onClick={()=>setSelected(e.exam_id)} style={{padding:'5px 14px',borderRadius:20,border:'none',cursor:'pointer',fontSize:12,fontWeight:600,background:selected===e.exam_id?'#7c3aed':'#f3f4f6',color:selected===e.exam_id?'#fff':'#374151'}}>{e.title}</button>))}
      </div>
      {myRank&&(<div style={{background:'linear-gradient(135deg,#f5f3ff,#ede9fe)',border:'1px solid #ddd6fe',borderRadius:14,padding:'16px 22px',marginBottom:16,display:'flex',alignItems:'center',gap:16,boxShadow:'0 1px 3px rgba(0,0,0,.05)'}}>
        <div style={{width:48,height:48,borderRadius:'50%',background:'linear-gradient(135deg,#7c3aed,#6d28d9)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:22}}>🏅</div>
        <div style={{flex:1}}><div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:18,color:'#1e1b4b',marginBottom:2}}>Your Rank: #{myRank.rank_pos}</div><div style={{fontSize:13,color:'#7c3aed'}}>Score: {Number(myRank.total_score).toFixed(1)}/{myRank.total_marks} · Grade: {myRank.grade}</div></div>
        <button className="btn btn-primary btn-sm">View Full Analytics →</button>
      </div>)}
      <div style={{background:'#fff',border:'1px solid #e8e8f0',borderRadius:14,overflow:'hidden',boxShadow:'0 1px 3px rgba(0,0,0,.05)'}}>
        <div style={{padding:'14px 20px',borderBottom:'1px solid #f3f4f6',fontFamily:'Space Grotesk,sans-serif',fontWeight:700,fontSize:15,color:'#0f0f1a'}}>Top Global Performers</div>
        {loading?<div style={{display:'flex',alignItems:'center',gap:12,padding:40,justifyContent:'center'}}><div className="spinner" style={{width:24,height:24}}/></div>
        :board.length===0?<div className="empty-state"><div className="empty-icon">🏆</div><div className="empty-sub">No results yet</div></div>:(
          <table style={{width:'100%',borderCollapse:'collapse'}}>
            <thead><tr style={{background:'#f8f8fc'}}>{['RANK','STUDENT','DEPT & YEAR','SCORE','PERCENTILE','GRADE'].map(h=>(<th key={h} style={{padding:'9px 16px',textAlign:'left',fontSize:9,fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1.5,fontFamily:'JetBrains Mono,monospace',borderBottom:'1px solid #f3f4f6'}}>{h}</th>))}</tr></thead>
            <tbody>{board.map((r,i)=>{const isMe=r.name===store.currentUser?.name,pct=Math.round(Number(r.total_score)/Number(r.total_marks)*100),color=gc(r.grade);return(
              <tr key={i} style={{background:isMe?'#faf5ff':'transparent',borderBottom:'1px solid #f3f4f6'}} onMouseEnter={e=>{if(!isMe)e.currentTarget.style.background='#f8f8fc'}} onMouseLeave={e=>{e.currentTarget.style.background=isMe?'#faf5ff':'transparent'}}>
                <td style={{padding:'12px 16px',fontSize:i<3?18:12,fontWeight:800,color:'#f59e0b'}}>{medal(i)||<span style={{color:'#9ca3af'}}>{i+1}</span>}</td>
                <td style={{padding:'12px 16px'}}><div style={{display:'flex',alignItems:'center',gap:10}}><div style={{width:32,height:32,borderRadius:'50%',background:'#ede9fe',display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:800,color:'#7c3aed'}}>{r.name?.charAt(0).toUpperCase()}</div><div style={{fontSize:13,fontWeight:700,color:isMe?'#7c3aed':'#0f0f1a'}}>{r.name}{isMe&&<span style={{fontSize:10,color:'#7c3aed',marginLeft:4}}>(You)</span>}</div></div></td>
                <td style={{padding:'12px 16px',fontSize:12,color:'#6b7280'}}>{r.department||'—'}<br/><span style={{fontSize:10,color:'#9ca3af'}}>{r.year||''}</span></td>
                <td style={{padding:'12px 16px',fontFamily:'JetBrains Mono,monospace',fontWeight:700,fontSize:13}}>{Number(r.total_score).toFixed(1)}/{r.total_marks}</td>
                <td style={{padding:'12px 16px',minWidth:120}}><div style={{display:'flex',alignItems:'center',gap:6}}><div style={{flex:1,height:4,background:'#f3f4f6',borderRadius:2,overflow:'hidden'}}><div style={{height:'100%',width:`${pct}%`,background:'#7c3aed',borderRadius:2}}/></div><span style={{fontSize:10,color:'#7c3aed',fontFamily:'JetBrains Mono,monospace',fontWeight:700,flexShrink:0}}>{pct}%</span></div></td>
                <td style={{padding:'12px 16px'}}><span style={{padding:'3px 10px',borderRadius:5,background:`${color}15`,color,fontSize:11,fontWeight:800}}>{r.grade}</span></td>
              </tr>
            );})}</tbody>
          </table>
        )}
      </div>
    </div>
  );
}
